(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-11"] = [{"a": [263], "v": 1, "p": 552, "ev": 1, "ep": 555, "sid": 553, "t": "قوله - عز وجل:\n﴿قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ﴾⟪2:263⟫ الآية: (263) - سورة البقرة ...\nالغنى: فقد الحاجة، وذلك يختلف باختلاف أحوال الناس واختلاف نظرهم فمنهم من يرى الغنى كثرة عرض الدنيا، حصلت معه الحاجة أو لم تحصل ومنهم من عده القناعة وإليه يوجه قوله عليه الصلاة والسلام: \" الغنى غنى النفس \" ومنهم من لا يعده إلا ارتفاع الحاجة وقال: \" لا غنى\n⟦1:553⟧\nفي الحقيقة في الدنيا يوجه ولأجله \" قيل: الغنى غنى الآخرة ومنهم من قال: \" لا غنى في الحقيقة لغير الله -عز وجل - لا في الدنيا ولا في الآخرة وعلى هذا \" قال تعالى: ﴿وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ﴾⟪47:38⟫ والمعنى المنزل كأنه موضع غنى الناس، ولكون الغنى مقيما فيه على مراده وعلى هذا قال الشاعر:\nيقيم الرجال الأغنياء بأرضهم ...\nويرمي النوى بالمقترين المراميا ..\nوأما الغناء فللتشبيه على نحو نظر من قال \" الغناء غذاء الأرواح، كما أن الطعام غذاء الأشباح، وقال ببعضهم: \" من مدح الغناء إنما مد الغناء وقصر الغنى تفضيلا للمدود \"، فقد حصل له منفعة ليست في شيء من اللذات، وذاك أن اللذات الحسنة أربع، أكل، وشرب، ونكاح، وغناء ..\n، وكل يوصل إليه بتعب إلا الغناء، واختلف في قوله: ﴿مَّعۡرُوفٞ وَمَغۡفِرَةٌ﴾⟪2:263⟫.\nفمنهم من قال: خطاب للمسئول ومعناه: لأن تبذل للسائل قولا حسنا، وتغفر له أن ذاك بمراجعة وإلحاف خير من أن تعطيه وتمتن عليها، كقول الشاعر:\nومنعك للندى بجميل قول\nأحب إلي من بذل ومنة\nوقيل: معنى المغفرة الترك، أي الاقتصار على القول الحسن، وترك الصدقة خير من صدقة هكذا، وقيل معناه: وإن تسأل الله الغفران لتقصيرك في إعطائه، وقيل: معناه ستر الخلة عليه، وقيل: ﴿قَوۡلٞ مَّعۡرُوفٞ﴾⟪2:263⟫ وسلامة من المعصية خير من المعصية خير من صدفة هكذا، فإن هذه الصدقة فيها\n⟦1:554⟧\nعصيان النص، ونحو قوله: ﴿قَوۡلٞ مَّعۡرُوفٞ﴾⟪2:263⟫ قوله: ﴿وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا﴾⟪17:28⟫، وقوله: ﴿وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ﴾⟪93:10⟫، وقيل: القول المعروف أن تحث غيرك على إعطائه، وقيل: ذلك خطاب للسائل وحث له على إجمال الطلب، كما قال عمر بن عبد العزيز: \" لن تدعوا لمرء ما قسم له، وفأجملوا في الطلب \"، فأراد تعالي لأن يقول قولا حسنا من تعريض بالسؤال أو إظهار للغنى، حيث لا ضرورة، ويكتسب خليط من مثال صدقة يتبعها أذى، كما قال الشاعر:\nلأن أرجي عند العرى بالخلق\n....\nوأجتزى من كثير الزاد بالعلق\nخير وأكرم لي من أن ترى نعم\n....\nمعقودة للئام الناس في عنقي ..\nوقيل: معناه: لأن تنال أيها السائل قولا معروفا من المسئول ومغفرة من الله خير من صدقة هكذا ..\nومنهم من قال: ﴿قَوۡلٞ مَّعۡرُوفٞ﴾⟪2:263⟫ خطاب للمسئول، أي: \" لتقل قولا حسنا في رده، ومغفرة خطاب للسائل \" أي: اغتفر رده لك ولا تثقلن قلبك عليه، ونبه بقوله: ﴿وَٱللَّهُ غَنِيٌّ﴾⟪2:263⟫ أن استقراضه ليس بحاجة به، بل لحاجة المقرض إلى الثواب، وبقوله \" حليم \"، أنه ليس يجب أن يغتر المذنب بتأخير العقوبة عمن قصر في الإنفاق أو في المنة على السؤال أو في سؤاله وليس بأهله ..\n⟦1:555⟧"}, {"a": [264], "v": 1, "p": 555, "ev": 1, "ep": 557, "sid": 556, "t": "قوله - عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ﴾⟪2:264⟫ الآية: (264) - سورة البقرة.\nالتراب أصل في بابه، وترب يخصص بالتراب، وعبر به عن الفقر، وأترب صار ذا تراب، وعبر به عن المختص بالمال الكثير، فكأنه عبر عن المال بالتراب كما عبر بالثرى، وقول الشاعر في مخاطبة الدلو:\n\" واغترفي من تربها الأدق \"\nتصور منه معنى ترب وأترب، ففسر مرة بأنه دعاء عليها، كأنه قال: تربت فلا تخرجين إلا ترابا، ومرة بأنه دعاء لها، والمعنى أتربت، فأخرجت ماء كثيرا، والترب للذة على بناء القبل والقرن أي المقابل والمقارن، وكأنه الواقع مع غيره في التراب عند الولادة، وقيل معنى الترب الملاعب مع غيره بالتراب في الصغر، كقوله:\nكما قسم الترب الصبي المقابل\nوالتريبة لعظم الصدر، حيث التفت عظام كأنها أتراب أي لدات، ولهذا قيل لها أتراب بلفظ الجمع، والوابل الذي يبل الأرض، أي يأتيها بالوبل، ويقال للمطر وابل ويرعى وبيل للنبات اليابس الذي يأتيه المطر، فيصير أذى للغنم وهو الذي يقال له النشر، ومنه اشتق الوبال وعنه استعير \" أخذه أخذا وبيلا \"، ويقال للعصا الثقيلة، وبيله الصلد، والصلت، والصلب تتقارب، لكن الصلد\n⟦1:556⟧\nخاص في الأرض والصخر وشبه به ما لا يجدي، فقيل: زند صلد، ورجل مصلد، وصلد: بخيل، وقدر صلود ذات صلدة يتباطأ غليانها، وفرس صلود: لا يعرق ..\n، وصفوان: أبلغ من الصفات، وهو كل حجر صاف من التراب، وواحده قيل: صفوانه: نحو سعدان وسعدانة، ومرجان ومرجانة، وقيل واحد، وجمعه صفوان، نحو كروان وليعظم الله تعالى فتح المنة، أعاد ذلك في معارض من الكلام، فأثنى على تاركها أولا، وفضل المنع على عطية يتبعها المن ..\nثانيا: وصرح بالنهي عنها بالياء، وخص الصدقة بالنهي إذ كان المنة فيها أعظم وأشبع ولكون ذلك فظيعا مستبشعا قال عليه الصلاة والسلام: \" ثلاثة لا يجدون ريح الجنة، وإن ريحها لتوجد من مسيرة خمس مائة عام: العاق لوالديه ومدمن الخمر والمنان \"، وقوله: ﴿كَٱلَّذِي يُنفِقُ مَالَهُۥ﴾⟪2:264⟫ في موضع الحال للمؤمنين، لا تبطلوها مثل منفق ماله مرائيا - تنبيها أن إنفاق الممتن كإنفاق المرائي الكافر بالله لأنه قال: ﴿كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ﴾⟪2:264⟫، وذلك كله من صلة \" الذي \" وقد عظم مزاياه حتى جعل المرائي بفعل الخير شرا من تاركه - سيما في العبادات، ولهذا قال - عليه الصلاة والسلام - \" المتشبع بما لم ينل كلابس ثوبي زور \" تنبيها أنه كاذب بمقاله وفعاله، وشبه المرائي بصفوان وماله بتراب، وإنفاقه بالوابل وبين أن إنفاق هذا المرائي مع كون الإنفاق في نفسه شيئا نافعا لم يفده إلا زوال ترابه، كما أن المطر الذي أتى على الصفوان مع كون المطر نافعا في نفسه لم يفده إلا زوال ثراه وقال تعالى في ضياع أعمال الكافر: ﴿مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ﴾⟪14:18⟫، وفي الآيتين دلالة أن\n⟦1:557⟧\nالعبادات والأعمال الصالحة وغير معنية ما لم يبن على الإيمان، ولا حجة في الآيتين ما لم احتج بهما على المرجئة، حيث قالت: إن المعاصي لا تحبط الطاعات لأنهم قالوا ذلك بشرط الإيمان، والله تعالى شرط في الآيتين الكفر، لأنه قال: ﴿كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ﴾⟪2:264⟫ وقال في الأخرى ﴿مَّثَلُ ٱلَّذِينَ كَفَرُواْ﴾.\nوهذا ظاهر، وقوله: ﴿لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ﴾⟪2:264⟫ راجع - إلى قوله: كالذي، أي المرائي بإنفاق ماله، لا يقدر يوم القيامة على اجتناء ثمرة ما اكتسبوا\nفإن قيل: وكيف يجوز أن يكون ﴿لَّا يَقۡدِرُونَ﴾⟪2:264⟫ فعلا للذي والذي هو فعلا للواحد؟ قيل: قد يقدر أن الذي قد يقع على الجمع، وأنه إذا أريد به الجمع، فقيد يخبر عنه كما يخبر عن الواحد وقوله: ﴿لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ﴾⟪2:264⟫.\nقد تقدم أن الهداية على أربعة أضرب هداية بالفطرة وهداية ببعث الرسل وهما عامان لكل مكلف، وهداية بالتوفيق لمن يستحق الاهتداء وهداية هي ثواب الآخرة، وهاتان لا تكونان للكافر"}, {"a": [265], "v": 1, "p": 557, "ev": 1, "ep": 559, "sid": 558, "t": "قوله - عز وجل:\n﴿وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ﴾⟪2:265⟫ الآية (265) - البقرة\nيقال: ربوة، وربوة، وربوة وربا حصل في ربوة، وسميت الربوة رابية كأنها ربت بنفسها في مكان بسيط ويقال لكل ما زاد وعلا ربا، ومنه الربوا والطل أثر الندى، والطلل: الأثر الباقي مما بلي، وطلت الأرض، أصابها طل، نحو وبلت، ومطرت وطل دمه: ترك أثره، وعلى ذلك ما قيل: إن سألتك بمرشكرها وشبرك أفشأت تطلها وتضهلها، وقيل: للشجر طل وندى لأنه من النبت والنبت منهما وبالعكس من ذلك قيل للندى والمطر شحم لأنهما يؤديان إليه بين تعالى أن المنفق ما له في سبيل الله ينبغي أن يكون قاصدا به الوجهين اللذين لأجلهما أوجب على الناس الزكاة، أحدهما ابتغاء\n⟦1:558⟧\nمرضاة الله وطلب التوجه للوصول إليه المشار إليه بقوله، مخبرا: ﴿إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا﴾⟪76:9⟫ والثاني: بتثبيت النفس أي رياضتها، لأداء الأمانات وبذل المعونات، والتمسح لأبواب المصالح فإن النفوس ما لم ترض لم تسمح، إذ هي مجبولة على الشح والكسل كما قال تعالى: ﴿إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا ۝ وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا﴾⟪70:19-21⟫ وببذل الصدقة وفعل الخير يتطهر ويتزكى ولهذا قال: ﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا﴾⟪9:103⟫ فهذان الوجهان أعنى ابتغاء وجه الله وتثبيت النفس وإن اختلفا اختلاف الاعتبارين فهما واحد، وحق الإنسان أن يقصد ذلك في جميع ما يفعله من العبادات، فاما أن يطلب شكر مخلوق ومباهاة نظير وطلب نفع دنيوي وقضاء شهوة وإبقاء معزة فليس ذلك بمرتضى وبين أن مثل نفوس المنفقين أموالهم على هذا الوجه كمثل روضة بربوة فشبه نفوسهم بالروضة وما يأتيهم من التوفيق والهداية من جهة الله بسبب الأنفاق بما يأتي الروضة من الوابل والطل وشبه تزكية النفوس بزكاة الأكل وقال جابر: الطل مثل للفرائض والوابل مثل للنوافل معهما، ومعناه: إن حق النفق ماله أن يتحرى النوافل والفرائض، فإن من لم يتحرهما معا، لم ينفك من الفرائض، تنبيها أن الفريضة هي ما لابد منه وتخصيص الربوة لأن تأثير الشمس فيها أكثر، ولما كان قد ينقطع عن الربوة فيحترق نباتها بين\nأنها لا تنفك من وابل وطل وعلى هذا قول الأعشى:\nما روضة من رياض الحزن معشبة. . . خضراء جاد عليها مسبل هطل\n⟦1:559⟧\nفوصفها بأنها في حزنة ومجودة ..\nإن قيل: ما وجه قوله تعالى: ﴿فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ﴾⟪2:265⟫ والضعف يقال في عدد ما يصح أن يوجد نصفه ولم يجرها هنا ذكر عدد ولا ما يقتضي عددا، قيل : إنه لما كان لكل قطعة أرض قدر من الريع لا يكاد يزيد عليه بين تعالى أن دخل هذه الجنة ضعفا ما يقتضي مثلها من الأرضين ..\nإن قيل: لم قال: ﴿وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ﴾⟪2:265⟫؟ فجمع جمع القلة؟ قيل: تنبيها أن ذلك الفعل لا يكاد يوجد إلا في قليل من الناس، فصار في تخصيص الأنفس إشارة إلي نحو قوله - عز وجل - ﴿وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ﴾⟪34:13⟫ ولهذه النكتة - قال تعالى: ﴿وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ﴾⟪12:106⟫ قال: عليه الصلاة والسلام لأصحابه: \" الشرك أخفى فيكم من دبيب النملة على الصفاة في الليلة الظلماء \"، تنبيها أنه قل ما ينفك عمل من رياء وإن قل.\nوبين تعالى بقوله: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ﴾⟪2:265⟫ أنه لا يخفي عليه شيء من أسرار العباد .."}, {"a": [266], "v": 1, "p": 559, "ev": 1, "ep": 562, "sid": 560, "t": "قوله - عز وجل:\n﴿أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ﴾⟪2:266⟫ الآية (266) - سورة البقرة.\nالنخيل: سمي بذلك لأنه منخول الأشجار وصفوها وذاك أنه أكرم ما ينبت، لكونه مشبها بالحيوانات في الاحتياج، الأنثى منها إلى الفحل في التلقيح وأنه إذا قطع رأسه لم يثمر بعده.\n⟦1:560⟧\nولأجله قال، عليه الصلاة والسلام: \" أكرموا عمتكم النخلة \" وقيل: نخل السماء الثلج عند وقوعه على الأرض قطن أو دقيق يغربل، والعنب والعناب نظر إليهما نظرا واحدا، وشورك بينهما في الحروف الأصيلة مشاركتهما في الهيئة والصيغة وزيد في لفظ العناب لزيادة جرمه على جرم العنب، وهذا طريق اعتبروه في الاشتقاق وتحت نقيض فوق وفي الحديث: \" لا تقوم الساعة حتى تظهر التحوت \"، أي ما تحت الأرض، وذلك إشارة إلى قال الله - عز وجل - ﴿وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ ۝ وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ﴾⟪84:3-4⟫\nوالعصر مصدر \" عصرت العنب \"، وسمى أخر النهار ومدة من الزمان عصرا كأنه مدة عصرت، فجمعت، وقيل للعطية عصر تشبيها بعصر الريح السحاب، وسمى الإلجاء عصرا والاعتصار\nالالتجاء، والمعصر سحاب ذات عصر للمطر، وامرأة فوق الكاعب معصر لكونها ذات عصر أي زمان\n⟦1:561⟧\nللتمتع إشارة إلى قول الشاعر:\nمطيات السرور فوق عشر ...\nإلى عشرين ثم في المطايا\nوالإعصار: أصله مصدر أعصر، فسمى به الريح والاحتراق مطاوعة حرق، وجرح الثوب أن تحرقه الدق، وحرق البعير حك إحدى نابيه بالأخرى، وريش حرق كالمنقطع بالإحراق، والحرقة احتراق البدن بحرارة فيه والحراق معروف، والحرقات سفن يرمى عنها بالنيران، ضرب الله مثلا لأعمال المنافق والمرائي، وأن لها في الدنيا شارة ونضارة، فإذا احتاج إليها وجدها باطلة، كمن له جنة هكذا يعتمدها، فلما اختل حاله، وكثر عياله، وانقضى شبابه، بقى خاليا عنها وعلى هذا دل ما روى أن عمر - رضي الله عنه قال: \" إني لأجد في نفسي من هذه الأشياء \"، وكان في القوم ابن عباس فقال: هذا مثل ضربه لمن يعمل عمره كله بعمل أهل الخير حتى إذا كان في آخر أيامه، وفي أحوج ما يكون إلى الخير، ختم عمله بعمل أهل الشقاء، فبطل ما عمل، وقيل: إن ذلك مثل ليس للمال فقط\n⟦1:562⟧\nبل للصحة والجمال وسائر الأمور البدنية والجارحة والسلطان، فإنه يفجع به الإنسان أحوج ما يكون إليه، فيكون بمنزلة من إذا كثر عياله فسد بالصاعقة بستانه، فبقى ضعيفا لأفضل فيه لعمل وسعى في تصرف، وإنما ذكر أنه فجع بها، ولم يقل: مات عنها، فالنفوس مطبوعا على استعظام ذهاب المال عن الإنسان أكثر من استعظام ذهاب الإنسان عن ماله، قالوا: حلف للأعداء، ولا يجنح إلى الأصدقاء\nإن قيل: كيف قال: \" أيود \" وهو مستقبل، ثم قال: \" وأصابه الكبر \"، فأتى بلفظ ماضي؟\nقيل: قد قال الفراء: لما كان يود يتلقى مرة بأن يكون، ومرة بلو كان، جاز أن يقدر أحدهما مكان الآخر، لإنفاق المعنى، فكأنه قيل \" أيود أحدكم لو كان له جنة، وأصابه الكبر \"،\nإن قيل: ولم قال: \" وأصابه الكبر \" ولم يقل: \" وكبر \"؟ في قوله: \" وأصابه الكبر تنبيه على معنى التأثير والنكاية فيه، كقول الشاعر:\nرمتني بنات الدهر من حيث لا أرى .."}, {"a": [267], "v": 1, "p": 562, "ev": 1, "ep": 564, "sid": 563, "t": "قوله - عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ﴾⟪2:267⟫ الآية: (267) - سورة البقرة.\nالطيب يقال تارة باعتبار الحاسة، وباعتبار العقل تارة، والخبيث في نقيضه، والأظهر أن المعني به هاهنا المعقول الذي هو الحلال، فقد روي: \" ثلاث إذا كن في التاجر طاب كسبه، لا يعيب إذا اشترى، ولا يمدح إذا باع، ولا يكذب \" وروي: لا يحلف.\n⟦1:563⟧\nوقال - عليه الصلاة والسلام:\n\" إن أطيب ما يأكل المرء من كسبه، وإن ولده من كسبه \"، وأصل التيمم قصد اليم أي لجة البحر، ثم صار في التعارف القصد نحو، ﴿فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا﴾، ويممته وأممته، قيل هما واحد وقال الخليل: أممته: قصدته من أمامه ويممته: قصدته من أي جهة كان والإغماض والتغميض غض البصر ويستعمل في الترخص كالإغضاء ذكر تعالى فيما تقدم فضل النفقة في سبيله، وحث عليها وقبح المنة، ونهى عنها وحث في هذا أن يكون الإنفاق من طيبات الكسب قيل: من أجوده، بدلالة ما روي أنه لما أمر بالصدقة، جاء قوم من أهل المدينة من صدقة التمر بالحشف ومن الطعام بالزوان فأنزل الله تعالى هذه الآية، وقيل الطيبات تتناول مع ذلك الحلال وحقيقة الطيب من الكسب ما ليس فيه ارتكاب محظور واكتساب محجور، بل منح العقل والشرع تناوله ودخل في قوله: \" ما كسبتم \" كل ما يناله الإنسان بريح أو أجرة عمل، وفي قوله ﴿وَمِمَّآ أَخۡرَجۡنَا﴾⟪2:267⟫ أنواع الحبوب والثمار والمعادن، وتخصيص المكتسب دون الموروث لأن الإنسان مما يكتسبه أضن منه مما يرثه، فإذا الموروث معقول من فحواه\nإن قيل؟ ما فائدة: لكم؟\nقيل: تنبيه أن المقصود بإتخاذ هذه الأشياء نفعنا ليبلغنا بها إلى سعادة الدارين، كقوله\n⟦1:564⟧\n﴿خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾⟪2:29⟫، ويجوز أن يتضمن مع ذلك أن الذي تجب فيه الزكاة، وهو ما قصد به قوام الإنسان دون ما قصد به البهائم كالحشيش ونحوه، وقوله: ﴿أَنفِقُواْ﴾⟪2:267⟫ عام في الواجب والتطوع ..\nإن قيل: لم قال: ﴿وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ﴾⟪2:267⟫ ولم يقل: (ولا تنفقوا الخبيث) مع أن اللفظ كان أوجز؟\nقيل: لأن القبيح من الإنسان أن يقصد الخبيث أي الرديء من جملة ما في يده فيخصه بالإنفاق في سبيل الله، فأما إنفاق الرديء لمن ليس له غير ذلك، أو لمن لا يقصده خصوصا فغير مذموما."}, {"a": [268], "v": 1, "p": 564, "ev": 1, "ep": 567, "sid": 565, "t": "قوله - عز وجل:\n﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ﴾⟪2:268⟫\nالآية: (268) - سورة البقرة.\nالفقر أربعة: فقر الحسنات في الآخرة، وفقر القناعة في الدنيا، وفقر المقتني، وفقرها جميعا والغني بحسبه، فمن حصل له في الدنيا فقد القناعة والمقتني فهو الفقير المطلق على سبيل الذم، ولا يقال له غني بوجه وهو المشار إليه بقوله عليه الصلاة والسلام \" كاد الفقر أن يكون كفرا \"، ومن فقد\n⟦1:565⟧\nلقناعة دون القنية، فهو الغني بالمجاز فقير بالحقيقة،\nولهذا قال: قد يكثر المال والإنسان مفتقر،\nوقيل لبعضهم: أفلان غني؟ فقال: لا أدري غناه، ولكنه كثير المال، ومن فقد القنية دون القناعة، إنه يقال له فقير وغني، وكلاهما يقالان على طريق المدح، فقد قيل: ليس الغني بكثرة العرض وإنما الغني غني القلب \"، والمشهور من الفقر عند العامة الحاجة وأصله كثير الفقار ومن قولهم: فقرته نحو كبدته، وبطنته، وبهذا النظر سمى الحاجة والداهية فاقرة، نحو: ﴿تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ﴾⟪75:25⟫، الفحش والفحشاء كل منكر من المقال والفعال وإن كان قد خصها بعضهم هاهنا بالبخل، كقول شاعر:\nأرى الموت يعتام الكرام ويصطفي. . . عقيلة مال الفاحش المتشدد\nفقوله: ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ﴾⟪2:268⟫، قيل: عنى فقر الآخرة وهو أن يخيل إليه أن لا جزاء ولا شكورا وقيل هو بأن يخوفه، الفقر في آخر عمره.\nإن قيل: على أي وجه يتصور وعد الشيطان؟\nقيل: إن ذلك تسليط النفس ووساوسه ولهذا قال هاهنا في الشيطان: ﴿وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ﴾⟪2:268⟫ قال في غيرها: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫ لما جريا مجرى واحدا،\n⟦1:566⟧\nقال: ﴿أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ﴾⟪36:60⟫، وقال في أخرى: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾⟪45:23⟫ الآية.\nإن قيل:\nمن حق مقابلة اللفظ في قوله ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ﴾⟪2:268⟫ أن يقول (والله يعدكم الغنى)، ويأمركم بالمعروف أو بالبر فليست المغفرة مقابلة للفقر ولا الفضل للفحشاء وإن كان مقابلا به، فلم لم يذكر في: (الله يأمركم)، والله يأمركم والله في الحقيقة يأمر فأما الشيطان فهو المسؤول الموسوس؟\nقيل: قابل الفقر بالمغفرة والفضل، والفضل أعم من الغنى، لأنه يتناوله وغيره، فبين أنه يعد بالغنى وزيادات فضل فأتى في مقابلة وعد الشيطان بالمغفرة، أنه يغفر مع ذلك انقيادكم للشيطان، وسائر الذنوب ولما كان أمر الشيطان بالفحشاء إنما هو لأجل وعده بالفقر لأن من خاف بخل بماله، والبخل سبب ارتكاب سائر الفواحش ولهذا قال - عليه الصلاة والسلام: \" وأي داء أدوى من البخل؟ \"، صار مستغنى أن يذكر في مقابله: ﴿وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ﴾⟪2:268⟫ بما ذكر من قوله: ﴿مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ﴾⟪2:268⟫ لأن أمر الله تعالى بالخيرات والحسنات معلوم وإنما المجهول أمر الشيطان، إذ كان أمره يخفى على الجهال وإنما يعرفه أولوا الألباب ..\n⟦1:567⟧"}, {"a": [269], "v": 1, "p": 567, "ev": 1, "ep": 568, "sid": 568, "t": "قوله - عز وجل:\n﴿يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ﴾⟪2:269⟫\nالآية (269) - سورة البقرة.\nقد تقدم أن الحكمة معرفة الموجودات، وفعل الخيرات بقدر طاقة البشر، وذاك عام فيما يدرك بالعقل وبالوحي، وإن كان قد خص في بعض المواضع بما يدرك بالعقل في نحو قوله: ﴿وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ﴾⟪2:151⟫، فقول ابن عباس: \" الحكمة هاهنا: علم القرآن ناسخه، ومحكمه، ومتشابهه \"\nوقول ابن زيد: \" إنها علم آياته وحكمه ومتشابه \" وقول السدى أنها النبوة، وقول إبراهيم: إنها الفهم، وقول غيرهم إنها الخشية كلها صحيح وإشارة إلى أبعاضها، ومن قال: عنى بالخير الجنة ومن قال: هو العلم الظاهر والباطن فصحيح، والحكيم يقال بمعنى الفاعل والمفعول نحو: ﴿فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ﴾⟪44:4⟫ أي محكم ثم بين أن حقيقة ذلك لا يتذكرها إلا أولوا الألباب وقد تقدم حقيقة اللب وماله من المزية على مقتضى لفظ العقل، وإليه أشير بقوله: ﴿إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ﴾⟪50:37⟫ وأما من قال: \" كل مكلف ذو لب \" حاصل له فبعيد عن معرفة حقيقته وما تقدم يغني عن بسط القول فيه هاهنا.\n⟦1:568⟧"}, {"a": [270], "v": 1, "p": 568, "ev": 1, "ep": 569, "sid": 569, "t": "قوله - عز وجل:\n﴿وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ﴾⟪2:270⟫\nالآية (270) - سورة البقرة.\nإن قيل: كيف قال: ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ﴾⟪2:268⟫، ثم قال ﴿يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ﴾⟪2:269⟫، ثم رجع إلى ذكر النفقة، وذلك كلمات متباينة في النظم متفاوتة في السرد؟ قيل: بل ذلك في نهاية حسن النظم، فإنه تعالى لما بين فضل الإنفاق في سبيله وحث عليه حذرنا من الجنوح إلي الشيطان وإلى شرور النفس، وحثنا على الاعتماد على الحق بقوله: ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ﴾⟪2:268⟫ الآية، ثم بين بقوله: ﴿يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ﴾⟪2:269⟫ أن ذلك أمر يعرفه المتخصص بالحكمة التي يؤثر الله بها من يشاء، ثم رجع إلي ذكر النفقة وبين أن ذلك موضوع عند من لا يسهو أولا ينسى، وصار ذلك الحكمة مع كونه متعلقا بما تقدم كالاستطراد والتنويه بذكرها والحث على معرفتها والتخصيص بها ..\nإن قيل: ما وجه تعقيب الإنفاق بالنذر ووجه الآيتين بقوله: ﴿وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ﴾⟪2:270⟫ بعدهما؟\nقيل: النذر عقد الإنسان على نفسه فعل البر بشرط أو بغير شرط، ولما كان فعل الخيرات ضربين مفروغا منه ومعزوما عليه بين أن كلا الأمرين لا يخفى عليه وذلك كلام متضمن للوعد والوعيد، وقال بعضهم: ليس النذر هاهنا ما يلتزمه الإنسان بالتطوع فقط، بل كل ما التزمه بالعقل أو بالشرع فنذر، وقيل الإشارة بالنذر إلى التطوع وبالإنفاق إلى الواجب، ثم بين أن من ظلم نفسه بتقصيره فيما يلزمه من ذلك أو ظلم غيرة، فماله أنصار وهو جمع نصير نحو: شريف، وأشراف،.\nوفي ذلك تنبيه على ما قال:\n﴿مَا لِلظَّٰلِمِينَ مِنۡ حَمِيمٖ وَلَا شَفِيعٖ يُطَاعُ﴾⟪40:18⟫\n⟦1:569⟧"}, {"a": [271], "v": 1, "p": 569, "ev": 1, "ep": 571, "sid": 570, "t": "قوله - عز وجل:\n﴿إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ﴾⟪2:271⟫ الآية (271) - سورة البقرة.\nخفي الشيء صار في خفية، والخفاء ما يستر به كالغطاء، وخفيته: أزلت خفاءه وذلك إذا أظهرته، وأخفيته أوليته ما دون القوادم من الريش ..\n، قال الخليل: لأنها تخفى إذا وقع الطائر قد أثني الله تعالى على إبداء الصدقات بقوله: ﴿فَنِعِمَّا هِيَۖ﴾⟪2:271⟫، وقال ابن عباس: هذا في صدقة التطوع فأما الفرض، فإظهاره أفضل، لئلايتهم، وقال الحسن وقتادة: إخفاء جميعه أفضل ومن الناس من يحتج بذلك في جواز إعطاء الصدقات في الصامت والناطق الفقراء دون الإمام، لقوله: ﴿وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ﴾⟪2:271⟫، وقال بعضهم: ليس القصد بذلك إعطاء الفقراء يدا بيد، بل القصد إخفاؤه، فإنك إن آتيت الساعي فقد أتيتهم لأن يده يدهما في الحكم، وبين أن إخفاء الصدقة أحمد، لأن قوله: \" خير \" إن جعلته في تقدير \" افعل \" فتفصيله ظاهر، وإن جعلته في تقدير: \" فعل \"، فالخير أبلغ معنى من مقتضى نعم، ولا قال في الإخفاء \" فهو خير لكم \"، فأكده بلكم، ثم قال: ﴿وَيُكَفِّرُ عَنكُم﴾⟪2:271⟫، ولم يصف الإبداء بذلك، ثم قال: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ﴾⟪2:271⟫ تنبيها أنه إن أخفى لا يخفى عليه ولا يضل عنه ويؤكد فضل إخفائه قوله عليه الصلاة والسلام \" سبعة يظلهم الله في ظل عرشه.\n،، وذكر رجلا تصدق بصدقة أخفاها حتى لا تعلم شماله ما تصدقت به يمينه .. \"، وقوله: ﴿فَنِعِمَّا هِيَۖ﴾⟪2:271⟫ قرئ مكسور النون والعين وكسر النون\n⟦1:570⟧\nإتباع لكسر العين، وقرئ بفتح النون وكسر العين وقرئ بسكون العين وكسر النون وتشديد الميم وبتخفيف الميم أيضا، والسكون بعيد لالتقاء الساكنين، وليس أحدهما حرف مدولين، والتخفيف كذلك لحذف لام الفعل أو الميم من ما، وكلاهما لا ينقاس وقوله: ﴿وَيُكَفِّرُ﴾⟪2:271⟫ إذا جزم فعطف على موضع الفاء، وإذا رفع فعطف على موضع الفاء، وإذا رفع فعطف على ما بعد الفاء نحو: ﴿مَن يُضۡلِلِ ٱللَّهُ فَلَا هَادِيَ لَهُۥۚ﴾⟪7:186⟫ ..\nإن قيل: ولم قال: ﴿وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ﴾⟪2:271⟫؟ فأدخل فيه من قبل (قد): قال بعضهم: من زائدة وقيل تنبيها أنه لا يكفر جميع المعاصي لأنه يكفر الصغائر بشرط اجتناب الكبائر عند قوم ويكفر الكل عن المسلمين بشروط اجتناب الكفر إن شاء عند قوم ..\n⟦1:571⟧"}, {"a": [272], "v": 1, "p": 571, "ev": 1, "ep": 573, "sid": 572, "t": "قوله - عز وجل:\n﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ﴾⟪2:272⟫ الآية: (272) - سورة البقرة .\nإن قيل: ما وجه أتباع هذه الآية لما تقدم؟\nقيل: روى عن النبي - صلى الله عليه وسلم - إنه والمؤمنين تحرجوا من مواساة الكافرين ومواصلة أقاربهم منهم، حتى إن النبي - صلى الله عليه وسلم - سأله يهودي فقال: لاحق لك وإن \" أسماء بنت أبي بكر \" امتنعت من مواساة جدها وامرأته، وإن الأنصار امتنعوا من الإنفاق على أصهارهم من الكفار فأنزل الله تعالى ذلك تنبيها أن ليس عليك هداهم وأن يهتدي الكافر وإنما عليك أن تهديهم أي تدعوهم إلي الهدى على الوجه المأمور به - تنبيها أنه لا يجب أن تمتنع من مواساتهم لذلك، ومن الناس من قال: هذا كان عاما في جميع الصدقات، فرضها ونفلها ثم نسخت الفريضة بقوله: ﴿إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ﴾⟪9:60⟫ الآية ومنهم من قال: هو مخصوص في النافلة دون الواجبة، وإليه ذهب ابن عمر والحسن، وروي أبو حنيفة أنه لما أنزل الله: ﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾⟪2:272⟫ تصدق الناس على الكفار من غير الفريضة، وقيل عنى بالهداية الغنى، أي ليس عليك أن تهديهم، وإنما عليك مواساتهم، فإن الله يغني من يشاء وتسمية الغنى، هداية على طريقة العرب في نحو قولهم:\n⟦1:572⟧\n\" رشدت واهتديت \" لمن ظفر، و \" غويت \" لمن خاب وخسر، وعلى هذا قال الشاعر:\n\" ومن يغو لا يعدم على الغي لائما \"\nوقيل: ليس لقوله: ﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾⟪2:272⟫ تعلق بالإنفاق، وإنما هو تسلية للنبي -ص-، وتنبيه أنك وإن أمرت أن تكثر حثهم على الإنفاق فليس يرجع عليك ملامة في تقصيرهم، كقوله: ﴿أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ﴾⟪10:99⟫ وقوله: ﴿وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ﴾⟪2:119⟫، وقوله: ﴿فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ﴾⟪24:54⟫ وقوله: ﴿وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ﴾⟪2:272⟫ كقوله: ﴿وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ﴾⟪10:99⟫ وقوله: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ﴾⟪6:35⟫ وقوله: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ﴾⟪2:272⟫ أي: أهل دينكم.\nقال سفيان بن عيينة:\nبين أن ما تنفقوا من صدقة فلأنفسكم وقوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫ يعني: أهل دينكم تنبيها أن حكم الفرض من الصدقة بخلاف حكم التطوع، فإن الفرض لأهل دينكم دون الكافرين ، وقال غير معناه: ما تنفقونه فإنه يحصل لكم ثوابه سواء أوصلتم إلى مؤمن أو كافر، وقوله: ﴿وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ﴾⟪2:272⟫ قيل: هي جملة في موضع الحال، كأنه قال:\n⟦1:573⟧\n﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ﴾⟪2:272⟫ إذ لم تنفقوا إلا ابتغاء وجه الله، أي إذا قصدتم به وجهه، وقيل: ذلك جملة معطوفة على جملة، ومعناه: \" ما تنفقوا من خير فلأنفسكم وأنتم تقصدون به قصدكم به وجهه فقط دون عوض \" ..\nإن قيل ة ما معنى قوله: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ﴾⟪2:272⟫ وهذا معناه كمعنى قوله: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ﴾⟪2:272⟫ ما ذكره النبي - صلى الله عليه وسلم - حيث يقول: \" اللهم اجعل لمنفق خلفا، ولممسك تلفا \"، ويعني به المنفق حيت ما يجب، وكما يجب، لا المنفق في عبارة وخسارة، وقوله: ﴿وَأَنتُمۡ لَا تُظۡلَمُونَ﴾⟪2:272⟫، وهو تعالى يجعل لكم بالواحد سبع مائة، كما ذكره في الآية المتقدمة، والوجه هاهنا قيل معناه القصد والجهة، وقيل معناه القصد به الذات نحو النفس، ومعناه: يقصد به ذات الله، لا طلب جزاء، ولا خوف عقاب، ولا غير ذلك من الوجوه التي يقصدها أبناء الدنيا بالإنفاق ..."}, {"a": [273], "v": 1, "p": 573, "ev": 1, "ep": 576, "sid": 574, "t": "قوله - عز وجل -:\n﴿لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ﴾⟪2:273⟫\nالآية: (273) - سورة البقرة.\nالعفة: حبس النفس لكن فضول الشهوات الرديئة من المأكل، والمنكح، والاقتصار علي البلغة التي لابد من المشار إليها بقوله تعال: ﴿إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ﴾⟪20:118⟫.\n⟦1:574⟧\nويقول النبي - صلى الله عليه وسلم - فيما يرويه سفيان:\n\" أريع من جاوزهن، ففيه الحساب: ما سد الجوعة، وكف العطشة، وستر العورة \"، أكن البدن \" ...\nويدخل في العفة الجود، لأنه قد قيل: الجود ضربان: أن يكون بما في يدك متبرعا، وأن يكون عما في يد غيرك متورعا، والزهد يقاربه إلا الزهد، يقال اعتبارا بترك عرض الدنيا، والعفة تقال اعتبارا بحبس النفس عن الشهوات، وتتلازمان، والعفافة بقية ما في الضرع كأنه قدر يمكن التعفف به، والإلحاف استشعار المسألة والاستقصاء فيها وتذرعها، يقال: لحفته: أي ألبسته إلحافا ككسوته، أي ألبسته كساء، والوسم والسيما تتقاربان لكن الوسم علامة محسوسة كسمة البعير، والسيما علامة متفرسة، وأصلها من السوم أي طلب الكلا، وطلب المبيع، وسوم الماشية أن تطلب لها المرعى وإن كان قل يستعمل في إرسالها.\nإن قيل: بم يتعلق قوله: ﴿لِلۡفُقَرَآءِ﴾⟪2:273⟫؟\nقيل: هو على ما ذكر سنين بدل من قوله: ﴿لِأَنفُسِكُمۡۚ﴾، فقد ذكر أنه يعني بأنفسكم أهل دينكم، فصار الفقراء بعضهم، فصح أن يبدل منه بدل البعض من الكل، وقيل: يتعلق بقوله: ﴿وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ﴾⟪2:272⟫، أي ما تنفقون لهم إلا تقربا إلي الله عز وجل-، فمعلوم أن من خص بنفقته هؤلاء، فإنه لم يقصد إلا وجه الله، وقيل: ذلك يتعلق بفعل مضمر يدل علي: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ﴾⟪2:273⟫، أو بقوله: ﴿يُوَفَّ إِلَيۡكُمۡ﴾⟪2:272⟫، أي يوف إليكم، ويوسع لأجل الفقراء إشارة إلى ما قال - عليه الصلاة والسلام: \" إنما تنصرون بضعفائكم وتمطرون وترزقون \".\n⟦1:575⟧\nوقال بعض الناس: اللام تتعلق بقوله: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ﴾⟪2:273⟫ المذكور من بعد، وهذا لا يصح لأن ما يتعلق بمعمول حرف الشرط لا يقدم عليه، وكذلك ما يتعلق بما بعد حروف العطف، وقد تقدم الكلام في الحصر والإحصار، وأن الإحصار أعم من الحصر، فإن الحصر يقال في منع العدو، والإحصار يقال فيه وفي منع الذي يكون من ذات الإنسان من العقل، أو الهوى، أو المرض، أو الخوف، فكل حصر إحصار، وليس كل إحصار حصرا، ولأجل عموم الإحصار قال قتاده وابن زيد: \" منعوا أنفسهم من التجارة خوفا من الكفار \"، وقال السدي: \" منعهم الكفار بالخوف وقيل: منعهم المرض، وقيل، حملوا على الحصر.\n، وقوله: ﴿لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ﴾⟪2:273⟫ أي: ذهابا لمنع العدو إياهم، وقيل، لمنع الله لهم وإلزامهم أنفسهم المرابطة في سبيله، ولم ينف عنهم القدرة، ولكن بين أن إيمانهم وأحوالهم تمنعهم عن الإخلال وكما هم بصدده، كقولك: \" أمرني الأمير بكذا، فلا أستطيع أن أخل به \"، وقوله تعالى: ﴿يَحۡسَبُهُمُ ٱلۡجَاهِلُ﴾⟪2:273⟫، أي الجاهل بحالهم، وقيل : إن ذلك فيمن له استغناء في الظاهر وبه فقر في الباطن أو فقر إلى الله لمعرفته بحقائق الأمور، وقوله: ﴿تَعۡرِفُهُم بِسِيمَٰهُمۡ﴾⟪2:273⟫، أي تتفرس فيهم أحوالهم، وذلك مما يدل على أن للفراسة حكما صادقا، وعليه دل قوله تعالى: ﴿وَلَتَعۡرِفَنَّهُمۡ فِي لَحۡنِ ٱلۡقَوۡلِۚ﴾⟪47:30⟫ وقوله: ﴿سِيمَاهُمۡ فِي وُجُوهِهِم﴾⟪48:29⟫، وقوله عليه الصلاة والسلام: \" اتقوا فراسة المؤمن فإنه ينظر بنور الله \"\nإن قيل: ما وجه ذكر ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ﴾⟪2:273⟫ في ثلاثة مواضع متقاربة وتعليق كل واحد بحكم غير حكم الآخر.\nقيل: إنه بين أولا ما ابتغى به الإنسان وجه الله، فنفعه راجع إلى نفسه، وبيم في الثاني أنه وإن لم يقصد به وجه الله خالصا، بل قصد به طلب ثواب، أو اتقاء من نار، أو غير ذلك من وجوه المصالح، فله ما قصده، وآتاهم الثواب في الثالث، حيث ذكر الانفاق للفقراء الذين أحصروا،\n⟦1:576⟧\nفقال: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ﴾⟪2:273⟫، إشارة إلى ما قال:\n(أعددت لعبادي الصالحين مالا عين رأت، ولا أذن سمعت)."}, {"a": [274], "v": 1, "p": 576, "ev": 1, "ep": 577, "sid": 577, "t": "قوله- عز وجل:\n﴿ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:274⟫\nالآية (274) - سورة البقرة.\nقد تقدم أن إنفاق الأموال عند بعضهم ليس إنفاق المقتنيات فقط، بل كل ما خص الله به الإنسان من النفس والبدن في العبادة والعلم والجاه وغير ذلك، لكن الأظهر أنه إنفاق المقتنيات وروي أنه لما نزل ذلك، كان مع أمير المؤمنين علي - رضي الله عنه - أرنعة دراهم فتصدق بدرهم ليلا، وبدرهم نهارا، وبدرهم سرا وبدرهم علانية، فقيل له في ذلك، فقال: \" أردت أن أستوجب من الله ما وعد به الذين يفعلون ذلك \"، والإنفاق في سبيل الله ضربان ضرب ظاهر وهو الصدقة على الفقراء، وضرب غير ظاهر، وهو الإنفاق في المباحات إذا كان متناولا حيث يجب ومنفقا على ما يجب وكما يجب، وقد نقدم ما قال بعضهم أن مباحات الأولياء كلها فرائض، فعنى بقوله: علانية ما عرفه الناس أنه صدقة، وبالسر مالا يعرفه صدقة إلا أولوا البصائر ، وإلى هذا أشار من قال إنها نزلت، في النفقة على الخيل فإن الإنفاق على الخيل في الظاهر ليس بقربة وقوله: ﴿بِٱلَّيۡلِ﴾⟪2:274⟫ إشارة إلى نحو ما روي أن بعض الأنصار نزل به ضيف، وكان عنده طعام طفيف فقدمه إليه في الظلمة بالليل يري أنه يؤاكله وهو يؤثر به حتى أثنى الله عليه، والقصد بالآية في الجملة نفقة من لا يرائي أن لا يداحي وإنما يقصد به مرضاة الله فقط ..\n⟦1:577⟧"}, {"a": [275], "v": 1, "p": 577, "ev": 1, "ep": 581, "sid": 578, "t": "قوله - عز وجل:\n﴿ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:275⟫ الآية (275) - سورة البقرة.\nالخيط: الضرب على غير استقامة كخبط البعير بيده، والرجل الشجر بعصاه، وقيل لمس الشيطان الإنسان الخبط والتخبط لكون أفعال المتخبط على غير استقامة، والخباط سمة على غير استواء والسلف من الأفعال المضايقة) ويراعى سببه معنى التقدم، يقال: أصم سالفه، والسالفة من الإنسان لتقدمها علي ما دونها من الأعضاء إدا اعتبر من الأعلى، وأسلفته في المال، وسلافة الخمر صفوها الذي يتقدم خروجه من العصير، والعود الرجوع، وأصله من العود، فعاد رجع إلي عوده، أي أصله، وسمي البعير المسن عودا، لأنه لما كان غاية سنها ذلك كأنه عاد إليه، وبيان ذلك أن الغرض والغاية بالذات شيء واحدا لأن الغاية هي بلوغ الغرض، وكان عرض الإنسان بناء دراما، فبناها علي ما بوأها عال بفعله إلى غرضه، فبناها على ما نواها الذي كان منه، وعلى هذا سمي الثوب لكونه ثابيا إلى ما كان الغرض من الغزل، وبهذا النظر قال: ﴿وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ﴾ فسمي انتهاء الإنسان الذي هو الهرم \" أرذل العمر \"، وعلى هذا قال: ﴿إِلَى ٱللَّهِ مَرۡجِعُكُمۡ﴾ فسمي ذلك رجوعا لما كان الغرض من الإنسان تلك الغاية، وفي العادة عادة، لكونها معادا للإنسان فيما يتعاطاه أو لكونها عائدا إلى الإنسان، ولهذا قال: إن التخلق يأتي دونه الخلق وهو يقال ...\nللبربط عود للمتحرية عود.\n⟦1:578⟧\nكما يقال للنبيد شراب، واستعارة اسم الجنس والنوع لبعض منهما من أجل الكناية أحد ما يجب أن يراعى في الاشتقاق، والربا الزيادة على رأس المال من الربوة على ما تقدم، لكن في تعارف العرب هو لدفع دين بزيادة أو لزيادة ثمن لزيادة في الأجل، وصار في شريعتنا اسما لذلك، ولبيع الأجناس الستة بعضها ببعض متفاضلا ولما يجري مجراه على مقتضى العلة على حسب اختلاف،\nالآية الثالثة، وقال بعض الفقهاء: البيع والربا لفظان عامان نظرا منهم إلى مقتضى، وقال بعضهم: هما مجملان، نظرا منهم إلى اعتبار شرائط فيهما لم تكن العرب تعتبرها، فصارت الأعراب لا تعرفها من دون المراجعة إلى صاحب الشرع، وكلا القولين صحيح بنظر ونظر، فإنهما عامان من وجه، ومجملان من وجه، ولذلك وصفهما الشافعي بالصفتين، فظن كثير من أصحابه أن قوله اختلف في ذلك، وردي في تفسير الآية أن المربى يقوم من قبره يوم القيامة مجنونا، وأنه في المحشر يصرع ويوطأ بالأرجل إلى أن يحاسب الله الخلائق، ثم يدخل النار، وفي قراءة ابن مسعود: \" لا يقومون يوم القيامة إلا كما يقوم \"، وقيل: معناه: من سوى بينهما يخرج في الآخرة من حد الأبرار إلى حال الدين اتبعهم الشيطان وكانوا من الغاوين، كما قال الله تعالى: ﴿وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا﴾⟪4:38⟫، وقيل: هو تشبيه من لم يفرق بين البيع والربا مع شدة تضادهما وتباين ما بينهما في أن البيع سبب العدل والعمارة للعالم، والربا سبب الجور وخراب العالم فنبه أن قبح الربا مركوز في العقول، بحيث أنما من سوى بينه وبين البيع فقد بلغ به الجهل إلى حد الجنون، وقوله: ﴿فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ﴾⟪2:275⟫، أي من انتهى بعد الوعظ، فما أخذه من قبل ملكه، لا اعتراض عليه، ولكن أمره في الآخرة إلى الله، إن شاء عاقبه، وإن شاء عفا عنه، وقيل: بل معناه: لا يؤخذ به في الدنيا ولا في الآخرة، ومعنى: ﴿وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ﴾⟪2:275⟫ على طريق الوعد له والسكون منه وأنه قد خرج من حزب الشيطان إلى حزب الله، كقوله تعالى: ﴿إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ﴾⟪5:55⟫.\n⟦1:579⟧\nوكقوله: (الصوم لي وأنا أجزي به)، وقوله: ﴿وَمَنۡ عَادَ﴾⟪2:275⟫، قيل: من عاد إلى تحليله وقيل: إلي تحليله أو إلى فعله من وغير استحلال، وقوله ﴿يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ﴾⟪2:275⟫ مما يدل أن الشيطان تأثيرا في الإنسان بخلاف ما زعمت المعتزلة، حيث قالوا أن لا تأثير في الإنسان للشيطان إلا بالوسوسة، قالوا: وهو أن يغلب عليه من المرء السوداء الضعف والقرع ما يحدث في المجنون، فمن\nقبل الله أومن قبل ذاته، وقال الجبائي: \" لو كان الشيطان يتخبطه بمسه لوجب أن يخبط كل واحد، فقد ثبتت عداوته للصالحين، ولوجب أن يسلب الإنسان ما في داره من أثاثه ومتاعه، فكان يحمل متاعهم إلى المسئ الكاذب \"، وقال أبو هاشم: \" لو قدر على ذلك لقدر على الصوت الرفيع، فكان يفشي سر المؤمنين ويضرب بينهم \"، فنقول وبالله التوفيق، إن أول ما في قولهم هذا إبطالهم لنحو ما حكي عن أيوب: ﴿مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ﴾⟪38:41⟫، وعن موسى: ﴿هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ﴾⟪28:15⟫، ولا يكذبهما تعالى فيما، وقال: ﴿لِلۡإِنسَٰنِ عَدُوّٞ﴾، وقال مخبرا عن الشيطان: ﴿وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ﴾⟪4:119⟫ واستثنى الله تعالي أولياءه بقوله: ﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾، هذا مع غيره من الآيات الباهرة الظاهرة،\nفإن قيل: على أي وجه يكون سلطانه؟.\n⟦1:580⟧\nقيل: على الوجهين اللذين ذكرهما الله أحدهما بالوسوسة، وهو أن يلقي في روع الإنسان أن أمرا ما يصير داعيا له إلى فعل يريده ويختاره، وإياه قصد بقوله تعالى: ﴿مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ﴾⟪114:4⟫.\nوالثاني: بدخوله في خلال جسده، وإياه عنى بقوله: ﴿ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ﴾⟪2:275⟫ وقال عليه الصلاة والسلام: \" الشيطان يجري من أبن أدم مجرى دمه \"، وما قالوه من أن، الشيطان لو قدر على خبط الإنسان لسرق ثيابه فلجهلهم بأمر الشيطان وجهة عداوته للإنسان وخصائص فاعله إلا أننا نرى أنما الحيات والعقارب تعادينا ولا تسرق أمتعتنا، وقد تقدم في ذكر السحر أن السحرة والشيطان لا يمكنها أن تفعل كل فعل كما ظنته المعتزلة، ولا أن تؤثر في كل واحد، وإنما تقدر على أفعال مخصوصة في أقوام ضعاف القلوب ومختلي العقول قليلي العبادة، وإذا أثرت تأثيرا ضعيفا، ويقوى ذلك مما روي في قصة خالد بن الوليد أنه لما وجهه النبي - صلى الله عليه وسلم - لهدم العزى تصور أنه خيال كان يفزع منه غيره إذا أبصره ويدبر عنه، فأقدم خالد لقوة قلبه وشدة شكيمته في الدليل، فهدمه، وإلى تخويف الشيطان الإنسان يرجع قوله مخبرا عن قوم هود: ﴿إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ﴾⟪11:54⟫ ولولا تلبيس الشيطان عليهم لما أقاموا على عبادة أجسام أموات وأشباح جماد، وقد وصف الله سبحانه ضعف سلطان الشيطان علي المؤمن فقال: ﴿إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ﴾⟪58:10⟫ الآية ...\n، واستبعاد المعتزلة تأثير الشيطان، إنما هو لخروجهم بتحديقهم عن حد العامة في التزام ما تلزمهم الشريعة الإقرار به، وقصورهم بسوء تصورهم وفساد طريقتهم عن إدراك حقائق ما ورددت ما به الشريعة حسب ما أدركه الحكماء الذين وصفهم الله بقوله: ﴿وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ﴾⟪2:269⟫ فصاروا في كثير من ذلك كما قالوا: \" لا مال أبقيت، ولا حرك أبقيت \".\n⟦1:581⟧"}, {"a": [276], "v": 1, "p": 581, "ev": 1, "ep": 583, "sid": 582, "t": "قوله - عز وجل -:\n﴿يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾⟪2:276⟫\nالآية (276) - سورة البقرة.\nالحق نقصان الشيء حالا فحالا بحيث تخفى تفاصيله، يقال: محقه، فالمحق ومنه قيل: المحاق لآخر الشهر، وتربية الصدقات في الدنيا أن يثمر مال صاحبها، وذلك أدنى عنى النفس، ويدخر له لواحد سبع مائه ثم قد يزيد زيادة بلا حساب كما وعد، وعلى هذا ما روي لكن النبي - صلى الله عليه وسلم -.\n\" إن الله يقبل الصدقات، ولا يقبل منها إلا الطيب، ويربيها لصاحبها كما يربي أحدكم مهره أو فصليه، حتى إن اللقمة لتصير مثل أحد \".\nقيل: ما الفرق بين الربا والبيع وكل واحد منهما أخذ ربحا على رأس المال؟\nقيل: الفرق بينهما ظاهر، وذاك أنه قد تقدم أن الناس متفتقر بعضهم إلي بعض وإن كل واحد، قائم بأمر آخرين، فلو أمروا أن لا يأخذ بعضهم ربحا على رأس ماله، لرغبوا عن التجارة لضياع سعيهم، فكان يتعذر لأحدنا أن يتحصل له في حالة واحدة أشياء محمولة من آفاق متباينة، والبائع يأخذ ما يأخذه من غير عوض ولا سعي، بل بتضييق فضلات ماله على المحتاجين من حيث لا يلحقه ضرر، فصار ذلك منه أكل مال الناس بالباطل المنهي عنه بقوله: ﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ﴾⟪2:188⟫ ولأنها المواساة واجبة بالشرع والعقل، فلو أبيح للناس الربا هو الشح الذي جبلوا عليه لأدى إلى سد باب المعروف وإلى أن لا يوقي الإنسان شع نفسه المذكور في قوله: ﴿وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾.\n⟦1:582⟧\nفإنه كان يدعو إلى أن يبخل وبخله يدعوه إلى منع الزكاة وترك المواساة، وذلك يؤدي به إلى حرص على تناول المال من كل وجه كالسرقة، والخيانة والغصب وعلى هذا قال جعفر بن محمد: \" إنما حرم الله الربا ليتقارض الناس \" وروي عن أبي أمامة عن رسول الله - صلى الله عليه وسلم -: \" مكتوب على باب الجنة: القرض بثمانية عشر، والصدقة بعشر أمثالها \".\nقال جعفر:\n\" لأن المستقرض لا يأتيك إلا وهو محتاج، والصدقة ربما وقعت في يد الغني \"\nإن قيل: لما قال: ﴿وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾⟪2:276⟫ ولم يقل: كل كافر وهو تعالى لا يحبهما جميعا؟\nقيل هو تنبيها على معنى لطيف، وهو أن الربا يدعو الإنسان إلى ترك الصدقة والزكاة وترك مواساة الناس والى أن يأخذ مال الغير بالباطل، كما أن فعل الصدقة يدعو إلي الاستكثار من الخير، ولهذا قيل: عودا مرا ما اعتاد، ومتى تعود الإنسان فعل الشرور يصير ذلك مانعا له عن الخيرات ومن الصدقة التي تطهر النفس فنبه الله بقوله: ﴿لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾⟪2:276⟫ أن المرابي يؤدي به رباه إلى أن يصير كفارا أثيما وهما بناءان للمبالغة فإذا صار كذلك، فإنه لا يكاد يتوب، وإذا لم يتب لم يحبه الله المحبة التي وعد بها التوابين في قوله: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫ فلهذا وجه تخصيص بناء المبالغة في ذلك .\n⟦1:583⟧"}, {"a": [277], "v": 1, "p": 583, "ev": 1, "ep": 583, "sid": 584, "t": "قوله - عز وجل:\n﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:277⟫ الآية: (277) - سورة البقرة.\nقد تقدم أن الإيمان في الأصل هو التصديق، ولا يكون التصديق إلا عن تحقيق، والتحقيق يقتضي العلم، فإذا: الإيمان مقتض للعلم، وهو وإن كان في التعارف للعلم والعمل بحسبه، ففي الأصل، للاعتقاد النفسي، ولهذا قيل ما جاء الإيمان في القرآن إلا مقرونا بالعمل الصالح، ومما يؤكد ذلك خبر جبريل لما سأل النبي - صلى الله عليه وسلم - عن الإيمان لم يذكر النبي - صلى الله عليه وسلم - الله في تفصيله شيئا من الأعمال، فإذا قول من قال: ليست الأعمال البدنية من الإيمان فصحيح على وجه، وقول من قال: هي من الإيمان فصحيح على وجه، ولكن لا يعتد بعلم لا يضامه العمل، وما أصدق في ذلك قول الشاعر:\nلا يطمع المرء أن تجتاب غمرته. . . بالقول إلا له جسرا له العمل\nوأتبع قوله ﴿وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾⟪2:277⟫ بإقام الصلاة وإيتاء الزكاة وإن كانا غير خارجين عن عمل الصالحات تخصيصا لهما لكون إحداهما أشرف العبادة البدنية، والأخرى العبادة المالية، وفائدة تعقيب أية الربا بهذه الآية تنبيه على منافاة ما يستحق بهذه الأعمال وما يستحق بتعاطي الربا .."}, {"a": [278], "v": 1, "p": 583, "ev": 1, "ep": 584, "sid": 584, "t": "قوله - عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:278⟫\nالآية (278) سورة البقرة.\nأمر تعالى بالاقتصار من الربا على رأس المال بقوله: ﴿وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ﴾⟪2:278⟫، وقيل معناه:\n⟦1:584⟧\nمعلوما وقوعه، فبين أن \" إن \" هاهنا لم يكن لوقوع شبهه في إيمانهم"}, {"a": [279], "v": 1, "p": 584, "ev": 1, "ep": 586, "sid": 585, "t": "قوله - عز وجل:\n﴿فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ﴾⟪2:279⟫ الآية (279) - سورة البقرة.\nالحرب معلوم، والحرب السلب لكون ذلك واقعا فيها، وسمي بعض آلاتها الحربة والأصل في الحربة اسم الفعلة.\nوالتحريب إثارتها والمحراب: قيل سمي لكونه موضع محاربة النفس والشيطان، وتسمية أشرف البقاع بالمحراب تشبيه لمحراب الصلاة بالإضافة إلى غيره من الأمكنة، والحرباء: دويبة تتلقى الشمس كأنها تحاربها والحرباء: مسمار تشبيها بالدويبة في الهيئة كقولهم: ضبة وكلب تشبيها بالضب والكلب.\nومعنى الآية: إن لم تفعلوا أمر الله ولم تنقادوا له بعد، يزول الأمر بتركه فأنتم في حكم المحاربين.\nقال ابن عباس: يقتضي ذلك أن المربي يستتاب فإن تاب وإلا قوتل، ولا يقتضي كفرهم، فإن المحاربة قد تطرق على ما دون الكفر كقوله تعالى: ﴿إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ﴾⟪5:33⟫، اتفق الفقهاء أن ذلك حكم المسلمين، ونبه بقوله: ﴿وَإِن تُبۡتُمۡ﴾⟪2:279⟫ أن من ترك ذلك، فلابد أن يرد إليه رأس المال لا يظلمهم الناس بأن يفوزوا بأصول مالهم، ولا يظلمونهم بأن يأخذوا زيادة على أصل مالهم، وقرئ (فأذنوا) أي: أعلموا ذلك غيركم وذلك يقتضدي معنى (فأذنوا) لأنه لا يكون الإنسان مؤذنا حتى يكون آذنا.\nوفي قوله: ﴿وَلَا تُظۡلَمُونَ﴾⟪2:279⟫ ما دل عليه قوله - عليه الصلاة والسلام - \" مطل الغنى ظلم \" وقوله إلى الواحد يحل عرضه وعقوبته فإحلال عرضه التغليظ عليه بالمطالبة وعقوبته حبسه.\n⟦1:585⟧\nذروا العمل به، وكالاهما يصح له اللفظ، فيحمل عليهما وروي أن النبي - صلى الله عليه وسلم - قال في خطبته بمكة: \" ألا إن كل ربا كان في الجاهلية، فهو موضوع، وأول ربا أضعه ربا العباس بن عبد المطلب \" وروي أن أهل الطائف صالحوا على أن لهم رباهم في الناس، فلما أسلموا امتنع بنو المغيرة من دفع الربا، وترافعوا في ذلك إلى عتاب بن أسيد عامل النبي - صلى الله عليه وسلم - على مكة، فكتب في ذلك إلى النبي - صلى الله عليه وسلم - الله، فكتب عليه الصلاة والسلام بالآية، ونبه تعالى بالآية أن المربي غير متق لله، فإن تقواه اتقاء معاصيه من المحظورات العقلية والشرعية، وقد تقدم أن تعاطي الفعل يدعو إلى جنسه خيرا كان أو شرا، فمن اتقاه في شيء ما فهو أقرب إلى أن يتقيه في غيره ..\nإن قيل: كيف قال: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ﴾⟪2:278⟫، ثم قال: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:278⟫؟\nقيل: سماهم مؤمنين لإقرارهم بالإيمان ثم بين بقوله: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:278⟫ أن من شرط الإيمان التزام أحكامه، فإن (فإن كنتم مؤمنين) فلابد من التزام ذلك، وقيل: معناه: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ﴾⟪2:278⟫ قولا التزموا ذلك إن كنتم مؤمنين فعلا وهذا يرجع إلى الأول، وقال مقاتل: معنى: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:278⟫ إذ كنتم مؤمنين ووجه قوله: إن (إن) مترددة فيما يتحقق وقوعه، وفيما لا يتحقق، و (إذ): تقال فيها كان\n⟦1:586⟧"}, {"a": [280], "v": 1, "p": 586, "ev": 1, "ep": 587, "sid": 587, "t": "قوله - عز وجل:\n﴿وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ﴾⟪2:280⟫\nالآية (280) - سورة البقرة.\nكان هاهنا بمعنى وقع، أي وإن وقع معسر، وقيل: هي ناقصة وتقديره وإن كان ذو عسرة غريما لكم، فحذف الخير لكون المعنى مفهوما، وهذا أجود، فإن التامة أكثر ما يعلق بها الأحداث دون الأشخاص، نحو: كان الخروج كقولك: اتفق للخروج، ولا تقول كان زيد، وأنفق زيد، وقيل: قراءة أبي: (وإن كان ذا عسرة).\nوقوله: فنظرة إلى ميسرة) أي: فعليكم انتظار، فقرأ الحسن: (فنظرة) بسكون الظاء.\nوقرئ مناظرة نحو: فاقرة، وكاذبة.\nواختلف هل يجب الانتظار في رأس مال الربا أو في كل دين؟ فمنهم من قال: النص يقتضي ذلك في كل، فإنه تمم حكم الربا، ثم ذكر اعتبار من عليه دين ربا كان أو غيره، وهو قول ابن عباس، والضحاك، والحسين.\nويؤكد ذلك قوله عليه الصلاة والسلام: \" من أنظر معسرا كان في ظل الله، أو في كنف الله يوم القيامة. \"، وقال عليه الصلاة والسلام: \" من شدد على امرئ في التقاضي إذا كان معسرا، شدد الله عليه في قبره. \"\nوقال شريح وإبراهيم، وروى عن ابن عباس أن ذلك في الربا خاصته والتصدق على المعسر ترك رأس المال عليه، نحو قوله في القصاص.\n﴿فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ﴾⟪5:45⟫، وقوله: ﴿إِلَّآ أَن يَصَّدَّقُواْۚ﴾⟪4:92⟫ أي تتصدقوا، فأدغم، وقرئ: (تصدقوا) بتخفيف الصاد على حذف إحدى التاء ين بدلالة الأخرى عليه، وقرئ: (ميسرة) بضم السين، وذلك لغتان نحو: مشربة، ومشربة وقرئ مجاهد (ميسرة)، ولم يجوزه البصريون لعدم مفعل في كلامهم، وذكر الكوفيون ألفاظا يسيرة من ذلك ليوم ردع أو فعال مكرم.\n⟦1:587⟧"}, {"a": [281], "v": 1, "p": 587, "ev": 1, "ep": 588, "sid": 588, "t": "وقوله - عز وجل:\n﴿وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ﴾⟪2:281⟫\nالآية (281) - سورة البقرة.\nقال ابن عباس.\nهي أخر آية نزلت من القرآن، فقال جبريل للنبي - صلى الله عليه وسلم -: \" ضعها في رأس الثمانين والمائتين من سورة البقرة، وقد تقدم الكلام في الفرق بين \": (اتقوا الله)، (واتقوا ربكم)، ﴿وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ﴾⟪2:281⟫ وما يجري مجراه؟ ومعنى الرجوع فليس على تصور رجوع إلي مكان بعد المقارنة كيف يكون ذلك وقد قال الله تعالى: ﴿مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ﴾⟪58:7⟫، وإنما ذلك رجوع، إما على ما ذكرنا في العود آنفا وإما على تصور خلقه أبانا المشار إليه بقوله: ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫ وعلى هذا: ﴿كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ﴾⟪21:104⟫، وقوله: ﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾، وقوله: ﴿وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ﴾⟪11:123⟫ وتوفية كل نفس ما كسبت جزاءها، إن خيرا فخيرا، وإن شرا فشرا، كقوله تعالى: ﴿وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ﴾⟪21:47⟫ الآية وقوله تعالى: ﴿وَهُمۡ لَا يُظۡلَمُونَ﴾⟪2:281⟫، أي: لا ينقص ثوابهم، ولا يزاد عقابهم ..\n⟦1:588⟧"}, {"a": [282], "v": 1, "p": 588, "ev": 1, "ep": 593, "sid": 589, "t": "قوله - عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ﴾⟪2:282⟫ الآية (282) سورة البقرة ..\nدنت الرجل: أخذت منه دينا، وأدنته: جعلته دينا، وذلك بأن تعطيه دينا، والتداين والمداينة تدافع ذلك والبخس والنخس يتقاربان، لكن النخس أن يصيب بدنه، أي مكان كان والبخس أن يصيب عينه، وعنه استعير بخس حقه، كقولهم عور حقه، وتباخسوا في البيع تغابنوا كأن كل واحد يبخس صاحبه عما يريده منه باحتياله، والسفه خفة في العقل ومقتضياته، ولهذا يقال: \" سفيه الرأي \" وسفيه اللسان \" و \" زمام سفيه \" على التشبيه ..\nوالسآمة ملك يورث الضجر، والصغر خلاف الكبر، وأصله أن يستعمل في المقدار، ثم يستعمل في الأحوال، ومنه صغر صغرا أو صغارا إذا تحاقر لاحتمال ضيم والقسط النصيب على سبيل العدالة،\nفإن قيل: فإذا كان القسط ما يقول، فكيف قيل: قسط إذا جار؟\nقيل: معنى قسط أخذ قسط غيره وذلك عدل، فصار قسط وأقسط في التناول والمناولة، كقولهم عطاء، وأعطى ..\nإن قيل: لم قال: ﴿إِذَا تَدَايَنتُم بِدَيۡنٍ﴾⟪2:282⟫، وتداينتم ينبئ عن الدين والمدين والتداين يقال في\n⟦1:589⟧\nالمجازاة فبين بلفظ الدين المراد والمقصود في هذا المكان أنه لما عقب بقوله: فاكتبوه ذكر لفظ الدين، ليبين أنه هو الذي حث على كتبه وكتب ذلك واجب عند الربيع، وإليه ذهب عامة الفقهاء، ومنهم من قال: هو في السلم خاصة، وحقيقة: (اكتبوه) حث على الاعتراف به وحفظه، فإن الكتاب خليفة اللسان واللسان خليفة القلب، فلما قال: فاكتبوه فقد حث على غاية ما يكون في ذلك من الاحتياط، وقوله: ﴿وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ﴾⟪2:282⟫، قيل: واجب على كل حال على كل كاتب، وقيل: واجب على الكفاية كالجهاد، وهو الصحيح والكتابة بين المتتابعين وإن كانت غير واجبة، فقد تجب على الكاتب إذا أتوه، كما أن الصلاة النافلة وإن لم تكن واجبة على فاعلها، فقد تجب علي العالم - تنبيها إذا أتاه مستفتي وقوله: ﴿كَمَا عَلَّمَهُ ٱللَّهُۚ﴾⟪2:282⟫ حث على بذل جهده في مراعاة شروطه مما قد لا يعرفه المستكتب، وقوله: ﴿وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ﴾⟪2:282⟫، أي: ليقر، ولولا وجوب الحكم بإملائه، لم يكن إملاؤه أولى من إملاء غيره، ولهذا قال: ﴿وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ﴾⟪2:282⟫ وذلك نظير قوله: ﴿وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ﴾⟪2:228⟫، لما كان قولهن مقبولا وعلى هذا قوله: ﴿وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ﴾⟪2:283⟫،\nإن قيل: جمع بين لفظ (الله) ولفظ (الرب) في قوله: ﴿وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ﴾⟪2:282⟫؟ قيل: إن لفظ الله يقال اعتبارا بالوله إليه أو العبادة له، ولفظ \" الرب \" يقال اعتبارا بكونه تعالى مربيا لعباده ومنعما عليهم، وقد تقدم أن الإنسان يعرف الله ربا قبل أن يعرفه معبودا وذلك بمعرفة نعمه يتوصل إلي معرفة فجمع هاهنا بين اللفظين، كأنه قال: \" اتقوه معتبرين بذاته ومعتبرين بنعمه \"، وأما تقديم لفظ (الله) على (الرب) فقد تقدم في بيان قوله تعالى: ﴿ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾، ولأن مراقبة ذاته تعالى أبلغ وأشرف من اعتبار نعمه فكأنه قيل: \" إن لم تلاحظوه، فلاحظوا نعمه اللازمة لكم \"، وقوله: ﴿فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا﴾⟪2:282⟫ أي مبذرا لقوله: ﴿وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ﴾⟪4:5⟫ وقيل: عنى بالسفيه النساء، وبالضعيف الصغير وبالذي لا يستطيع أن يمل هو المغلوب على عقله، ومنهم من حمل السفيه والضعيف على شيء واحد، وقال أو زائدة، وذلك ظاهر الفساد في اللغة وقوله: ﴿وَلِيُّهُۥ﴾⟪2:282⟫ أي: ولي أحد هؤلاء الثلاثة، ولا يجوز أن\n⟦1:590⟧\nيكون ولي الحق كما قال بعضهم، لأن قوله لا يؤثرا إذ هو مدع.\nوقوله: ﴿بِٱلۡعَدۡلِۚ﴾⟪2:282⟫ حث على تحريه لصاحب الحق وللمولى عليه، وقوله: ﴿شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ﴾⟪2:282⟫ قال بعضهم: تقتضي هذه الإضافة الإيمان والحرية والبلوغ لتخصيص الرجال ويقتضي \" من ترضون من الشهداء \" العدالة، لأن المقصد من الاستشهاد إقامة الشهادة، أما شهادة العبيد والصبيان، وشهادة النساء في غير، وشهادة الأعمى والفاسق وغير ذلك من أحكام الشهادة، فكتب الفقه به أولى، وقوله: ﴿فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ﴾⟪2:282⟫ أي وليشهد رجل وامرأتان وقوله: ﴿فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ﴾⟪2:282⟫ أي تذكر الأخرى إذا نسيت وقال سفيان بن عينية: يجعلها كذكر في الحكم ..\nإن قيل: ما وجه قوله: ﴿أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ﴾⟪2:282⟫ وذلك يقتضي أن يكون القصد بالاستشهاد الضلال قيل: قد قال سيبويه في ذلك: لما كان الضلال سبب الأذكار وهو متقدم عليه صار لتعلق كل واحد منهما بالآخر في حكم واحد، قال : ومثل ذلك من قال أعددت هذا الخشب ليميل الحائط فأدغمه قال الفراء: تقديره: فتذكرها إن ضلت لكن لما قدم أن - فتح فصار متعلقا بما قبله: وهذا طريق في مسائل، وقرأ حمزة (أن تضل)، وقرئ ﴿أَن تَضِلَّ﴾⟪2:282⟫ من أضللت، لتقارب ضل وأضل تقارب نسيت وأنسيت وقيل: (أن تضل) أي تضيع شهادتها ما لم تضامها الأخرى إشارة إلى ما فاله عليه الصلاة والسلام: \" أما نقصان عقلهن فشهادتهن على النصف من شهادة الرجال \" وقوله: ﴿وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ﴾⟪2:282⟫ قال قتادة والربيع: \" إذا ما دعوا لتحمل الشهادة \"، وقال مجاهد: لإقامتها، وقيل: لهما، وهو الصحيح، وقال بعضهم: لا يجوز أن تكون للتحمل، لأنه حينئذ لا يكون شاهدا، وهذا سوء تصور منه ألا ترى أنه قال: ﴿وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ﴾⟪2:282⟫؟\n⟦1:591⟧\nفسماهما شهيدين، قيل: إن استشهد وبين قوله: ﴿وَلَا تَسۡـَٔمُوٓاْ﴾⟪2:282⟫ إن قليل الدين وكثيره يستحب كتابته وبين علة ذلك بقوله: ﴿ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ﴾⟪2:282⟫ أي أعدل، وأقوم للشهادة أي أثبت، ﴿وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ﴾⟪2:282⟫ أي أبعد من أن تقع شبهة ثم استثنى ما كان حاضرة، وخفف الأمر فيما لا أجل فيه وما لا يكون له ثبات في مكان كما الدور والعقار، نحو الطعام والشراب، وقوله: ﴿وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ﴾⟪2:282⟫ قيل: \" هو يرجع إلى الأول دون ما يكون تجارة حاضرة، وقيل: يرجع إلى الكل حتى قال بعضهم.\nيشهد على سامع حتى على ناقة.\nقيل وقوله: ﴿وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ﴾⟪2:282⟫ قرئ بفتح الراء \" لا يضارر \" بأن يدعي وهو مشغول، عن ابن مسعود ومجاهد، وقيل: ة هو يضار، أن: لا يمتنع الكاتب من الكتابة، والشهيد من، إقامة الشهادة عن الحسين وقتادة وابن زيد، لئلأ يؤدي إلي أبطال الحقوق، وقوله: ﴿وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ﴾⟪2:282⟫ خطاب للجميع على سبيل الوعيد، وقوله: ﴿وَٱتَّقُواْ ٱللَّهَۖ﴾⟪2:282⟫ إعادة للوصية،\nإن قيل: كيف قال: ﴿وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ﴾⟪2:282⟫ وكرر لفظ (الله) ثلاث متواليات ولم يعدل إلى الكناية، وهل ذلك في استقباح خط الإعادة لولا شرف لفظ (الله).\nكقول الشاعر: \" فما للنوى جد النوى قطع النوى \"\nحتى قيل: \" سلط الله على هذا البيت شاة ترعى منه النوى \"،\nوكقول الأخر:\nبجهل كجهل السيف والسيف منتضي ...\nوحلم كحلم السيف والسيف مغمد\nفاسترذل البيت لإعادة لفظ \" السيف \" مرارا ...\n، قيل: إن ذلك بعيد عن الآية، فإن البيت الأولى استقبح لا لإعادة النوى فقط، بل له، ولأن قول \" جذ النوى قطع النوى \" بمنزلة واحدة، ولهذا الباب\n⟦1:592⟧\nقانون يعرف به المستقبح من المستحسن، وهو أن كل تكرير على طريق تعظيم الأمر وتحقيره في جمل مواليات كل جملة، ومنها مستقلة بنفسها، فدلك غير مستقبح، وإذا كان ذلك في جمله واحدة أو في جمل في معنى واحد، أو لم يكن فيه التعظيم أو التحقير، فذلك مستقبح، وهذا ظاهر في الآية والأبيات المذكورة، فإنما قوله: ﴿وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ﴾⟪2:282⟫ حمل في معان مفترقة، فإن الأول: حث على تقوى الله، والثاني: تذكير بنعمه، والثالث: تعظيم له متضمن لوعد ووعيد شديد وفصد عظيم كل واحد من هذه الأحكام، فأعيد لفظ (الله) فيها ..\nفأما البيت الثاني: فهو جملة واحدة، لأن قوله: كجهل السيف في موضع لقوله: يجهل، وكذلك قوله: \" والسيد مغمد \" جاء لقوله: الحلم للسيف، وعلى قول الآخر:\n\" لا أري الموت يسبق والموت شيء \"\nفإن قوله: (يسبق الموت) \" مفعول ثان \" لقوله: ﴿لَآ أَرَى﴾، والكلام كله جملة واحدة، وهذا ظاهر ...\n⟦1:593⟧"}, {"a": [283], "v": 1, "p": 593, "ev": 1, "ep": 594, "sid": 594, "t": "قوله - عز وجل -:\n﴿وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ﴾⟪2:283⟫\nالآية (283) - سورة البقرة.\nالرهن: حبس السلعة بحق، ثم يستعمل في غيره على طريق التشبيه واؤتمن: أخذه واستوفاة كقولهم اكتحل واغتسل إذا استوفى ذلك وقيل: رهن، ورهن، ورهن فرهن، نحو ثمر، ورهن على التخفيف قيل: رهان، كقولهم: ثمار، وكلاب، وقال بعضهم: ليس الرهان إلا في المخاطرة، وحكم الرهن ثابت في الحضر والسفر عند عامة الفقهاء، وبعضهم خص حكمه بالسفر عند عدم الكاتب، وقرأ ابن عباس: (فلم تجدوا كتابا .. ) أي صحيفة ودواتا، وقوله: \" فرهان \" أي فليدفع رهانا، أو فليوجد رهانا، واشتراط كونها مقبوضة تنبيه أن الرهن لا يثبت حكمه ما لم يكن مقبوضا لأمرين ..\nأحدهما: أن ذلك معطوف على الشهادة فكما أن الشرط في الشهادة معتبر كذلك هاهنا والثاني: أن حكم الرهن مأخوذ من هذه الآية وقد أجازه بهذه الصفة، فيجب أن تعتبر الصفة فيه وأما حكم ما يجوز رهنه وما لا يجوز، وما يصححه ويفسده، فكتب الفقه أولى به وقوله: ﴿فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا﴾⟪2:283⟫ يحث من يؤتمن على حفظ الأمانة كقوله: ﴿إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا﴾⟪4:58⟫، وحذر غاية التحذير بقوله: ﴿وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ﴾⟪2:283⟫، وقوله: ﴿وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ﴾⟪2:283⟫ خطاب لمن عليه الحق، وللشاهد جميعا، لأن الشهادة إعلام، ويقال للإقرار شهادة، ولهذا قال تعالى: ﴿كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾⟪4:135⟫، وكما أن كتمان الشهادة محرم فما هو منه بسبب\n⟦1:594⟧\nمحرم كالتأخر عن إقامتها عن تحملها في بعض الأحوال وقوله: ﴿وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ﴾⟪2:283⟫ أي يأثم بذلك قلبه، ويجوز أن يكون معناه: \" إنما يكتم الشهادة ومن يكتم لأنه قد أثم قلبه \" قيل فحمله ذلك على ارتكاب المحارم واحتقاب المآثم، وإضافة الإثم إلى القلب مبالغة في الذم، فالقلب مقر البر والإثم، ولهذا قال: ﴿وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ﴾⟪64:11⟫، وقال بعضهم: \" في أية الدين صلاح للدين والدنيا \"، فالإنسان بمراعاة ما أرشده الله إليه فيهما يبعد عن جحود الحق الذي هو سبب التنازع، والتنازع سبب كل شر ولذلك قال تعالى: ﴿وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ﴾⟪8:46⟫، ومن هذه الوجه منع من البيعات المجهولة وجهل المدة وسائر الأشياء المؤدية إلى المنازعة، أوجب الإشهاد من أوجبه، لأن كل ما يؤدي إلى فساد فحسم مادته واجب .."}, {"a": [284], "v": 1, "p": 594, "ev": 1, "ep": 597, "sid": 595, "t": "قوله - عز وجل:\n﴿لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ﴾⟪2:284⟫ الآية (284) - سورة البقرة.\nقد تقدم ما هو جواب عن سؤال من قال: لم قال الله: ﴿مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ﴾⟪2:284⟫ ودلالة خطابه تقتضي أن ليس له السماوات والأرض، وقال بعض الصوفية في قوله: ﴿لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ﴾⟪2:284⟫ تنبيه أنه لا يجب الاشتغال بهما، بل يجب الاشتغال بمن أوجدهما وملكهما - تنبيها أن من تركها وأقبل عليه ملكه إياهما وما هو أفضل منهما، وإياه قصد بقوله: ﴿لَا تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ﴾⟪41:37⟫،\nإن قيل: ما وجه نظم هذه الآية مع ما قبلها؟ قيل: إنه لما فرغ من حكم الإيمان والعبادة والأحكام المذكورة في هذه السورة، ختمها بالموعظة ونبه على وجوب تفويض الأمر إليه، ولما كانت حقيقة العبادة متعلقة بالقلب، ولهذا قال عليه الصلاة والسلام: \" أخلص يكفك القليل من العمل \"، وهو أحد ما أفاد قوله - عليه الصلاة والسلام: \" البر ما اطمأن إليه\n⟦1:595⟧\nالقلب \" وقوله: ﴿وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ﴾⟪2:284⟫، كقوله: ﴿سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ﴾⟪13:10⟫، وقوله: ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ﴾⟪2:235⟫ ..\nإن قيل: هذه الآيات تقتضي أن يكون الإنسان مؤاخذا بما تتحرك به الخواطر، وقول النبي - عليه الصلاة والسلام ينافيه في الظاهر \" إن الله تجاوز عن أمتي عما حدثت به أنفسها \" وكذلك قوله: من هم بحسنة فلم يعملها كتبت له حسنة فإن عملها كتبت له عشر أمثالها، ومن هم بسيئة فلم يعملها لم تكتب عليه ..\nقيل: قد تقدم إن أول ما يعرض من حديث النفس السابح ثم الخاطر، ثم الإرادة والهم، ثم العزم وأن السابح والخاطر متجافي عنهما بكل وجه وأنه متى صار نية، فذلك عمل مأخوذ به وعلى هذا قال تعالى: ﴿وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ﴾⟪6:120⟫ ﴿وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ﴾⟪6:151⟫، وألهمه متى كانت من وسوسة الشيطان وتصدي الإنسان لدفعها وقمعها فهو المتجافي عنها بل هو الموعود بالإثابة على دفاعها، حيث قال عليه الصلاة والسلام: \" جاهدوا أهواءكم كما تجاهدون أعداءكم \"، ومتى كانت نفس وإجماع من النفس، فذلك فعل منه، ولذلك قال بعض الصالحين: \" عليكم\n⟦1:596⟧\nبحفظ الهمة ، فإنها أول ما تظهر من الإنسان وهي تقدمة الأشياء \" وقال عليه الصلاة والسلام: \" لينظر أحدكم ما يتمنى، فإنه لا يدري ما كتب له \" ومن تصور هذه الجملة علم أن قول من قال هذه الآية منسوخة بقوله: ﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ﴾⟪2:286⟫ وجعل علة النسخ أن حديث النفس وما يهجس فيها غير مقدور على صرفه، فإنما استعمل لفظ النسخ في معنى التخصيص، فأما أنه أمر بما لا يقدر عليه ثم نسخ، فمجال وعلى هذا ما روي أنه قيل لابن عباس إن ابن عمر يبكي لقوله: ﴿وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ﴾⟪2:284⟫ فقال ابن عباس: \" رحم الله ابن عمر، لقد وجد المسلمون منها ما وجدوا \" حتى نزل ﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ﴾⟪2:286⟫، فإنه عنى أن هذه الآية مخصصة ومبينة للأولى ونبه بقوله: ﴿فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ﴾⟪2:284⟫ على سعة قدرته وعدله وفضله ثم من الذي يغفر له والذي لا يغفر له لا يعقل من ظاهر الآية.\n⟦1:597⟧"}, {"a": [285], "v": 1, "p": 597, "ev": 1, "ep": 599, "sid": 598, "t": "قوله - عز وجل:\n﴿ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ﴾⟪2:285⟫ الآية (285) - سورة البقرة.\nإن قيل: لم لم يذكر هاهنا اليوم الآخر، وقد ذكره في قوله: ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ﴾⟪4:136⟫ الآية؟\nقيل: لأمور: أحدها أنه نبه عليه بذكرها في غيرها، والثاني: أن الإيمان بكتبه ورسله مقتض للإيمان باليوم الآخر أظهر عند المؤمنين من أن يحتاج إلى ذكره مفصلا، ألا ترى أنه قال: ﴿ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ﴾⟪2:285⟫ فاقتصر على ذلك ولم يصفه بما وصف به المؤمنين بقوله: ﴿وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ﴾⟪2:285⟫ تنبيها على أن ذلك بحيث يستغنى عن ذكرها وهذا الجواب علي قراءة من وقف على فوله: ﴿مِن رَّبِّهِۦ﴾⟪2:285⟫ ...\nوالرابع: إن في قوله: ﴿وَإِلَيۡكَ ٱلۡمَصِيرُ﴾⟪2:285⟫ دلالة على إيمانهم باليوم الآخر، وقال بعضهم: إنما أفرد إيمان اللنبي - صلى الله عليه وسلم -، فقال: ﴿ءَامَنَ ٱلرَّسُولُ﴾⟪2:285⟫ ثم قال: ﴿كُلٌّ ءَامَنَ بِٱللَّهِ﴾⟪2:285⟫، تنبيها على شرف إيمانه - عليه الصلاة والسلام-، وأنه سابق لإيمانهم، وأن لا واسطة بمنه- عليه الصلاة والسلام-، وبين الإيمان كما بين إيمان المؤمنين وبين الإيمان به واسطة، وقرأ \" ابن عباس \" وكتابه \"، قال: وهو أبلغ، لقوله: ﴿وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ﴾⟪57:25⟫، ولأن الكتاب للجنس، ولأنه ليس مع\n⟦1:598⟧\nكل نبي كتاب مفرد، بل في الأنبياء من استعبد بكتاب الله من يقدمه وقوله: ﴿لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ﴾⟪2:285⟫، أي: يقولون ذلك ولم يعن أنهم يتفوهون به فقط، بل يعتقدون ويتحرون مقتضاه بخلاف اليهود والنصارى، حيث آمنوا ببعض وكفروا ببعض، ولأن تابع الحق والحقيقة هو الذي يعرفه، ومن عرفه تبعه حيث وجده، فامحق من حيثما هو حق لا يخالف بعضه بعضا، وإنما الباطل هو الذي يتناقض ولا يتطابق، ومن هذا الوجه قال: ﴿وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا﴾⟪4:82⟫.\nوإذا كانت الأنبياء على الحق، فلا يعاند بعضهم بعضا، إذ لا معاندة في الحق ...\nإن قيل: لم قال: ﴿لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ﴾⟪2:285⟫ وبين تستعمل في شيئين فصاعدا، فكيف قال: ﴿بَيۡنَ أَحَدٖ﴾⟪2:285⟫؟ أيتناول الجنس على طريق الجملة والتفصيل ولذلك لا يستعمل إلا في الاستفهام والنفي فنبه بذكره هاهنا أنه لا يفرق بينهم لأعلى طريق الجملة وعلى طريق التفصيل.\nوقال في الكفار: ﴿إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ﴾⟪4:150⟫\nوقاله: ﴿سَمِعۡنَا وَأَطَعۡنَاۖ﴾⟪2:285⟫ أي سمعنا قولك، وأطعنا أمرك بخلاف من قال: ﴿سَمِعۡنَا وَعَصَيۡنَا﴾ وقوله: ﴿غُفۡرَانَكَ﴾⟪2:285⟫، أي \" أنزل غفرانك \"، أو نسألك غفرانك، واغفر لنا غفرانك، وكل ذلك متقارب، \" واليك المصير \" اعتراف بما وعدهم بقوله: ﴿وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ﴾⟪11:123⟫\n⟦1:599⟧"}, {"a": [286], "v": 1, "p": 599, "ev": 2, "ep": 400, "sid": 600, "t": "قوله - عز وجل -:\n﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ﴾⟪2:286⟫\nالآية: (286) - سورة البقرة.\nالقدرة والجهد والاستطاعة قد تقدم الكلام فيها، وكسبت واكتسبت قل يجريان مجرى واحدا، ويقال لما أخذته لنفسك ولغيرك كسبت، ولهذا قد يعدى إلى مفعولين، فيقال: \" كسبت فلانا كذا \"، واستقبح \" اكتسبته كذا \"، والاكتساب لا يقال وإلا لما استفدته لنفسك، فكل إكتساب كسب، وليس كل كسب اكتسابا، ولهذا انظائر فيه اللغة نحو: \" خبر، وطبخ، وشوي \" إذا فكل ذلك لنفسه أو فعله لغيره، ويقال: \" اختبز، واطبخ، واشتوى \" إدا فعل ذلك لنفسه ..\nوالإصر: الثقل وأصله من أصره إذا وعطفه، وقيل للعهد والرحم وكل ما يوجب عليك حماية ما إصر وكل آصر عاطف لمن مر به \"، والإصار كساء يجعل فيه حشيش، فيثنى على السنام بين الله تعالى أنه كلف عبده دون ما تنوء به قدرته، فإن الوسع هو القدرة على أكثر قدر المكلف، وقوله: ﴿لَهَا مَا كَسَبَتۡ﴾⟪2:286⟫ قيل: عنى بالكسب ما عمله من الخير، وبالاكتساب ما عمله من الشر، وقيل: عنى بالكسب ما يفعله الإنسان من فعل خير وجلب نفر من حيثما يجوز إلى غيره، والاكتساب ما يحصله،\nلنفسه من نفع يجوز تناوله، فنبه أن ما يفعله الإنسان من نفع غيره فله الثواب، وليس عليه فيه الحساب، وأن ما يحصله لنفسه وإن كان متناول من حيثما يجوز على الوجه الذي بجوز.\nفعليه فيه الحساب يؤيده ما ذكرنا من الفرق بين كسب واكتسب، وقوله: ﴿لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ﴾⟪2:286⟫ فإنه عنى النسيان الذي هو الترك أو ذهاب الذكر الذي الإنسان سببه لقلة مراعاته، وكذا الخطأ إنما أدار به ما يكون سبب حصوله، وقد تقدم الكلام في حقيقيهما.\nوقوله: ﴿مَا لَا طَاقَةَ لَنَا بِهِۦۖ﴾⟪2:286⟫ يعني: ما يثقل\n⟦1:600⟧\nحمله من الأمور الشاقة التي كلف كثيرا منها بني إسرائيل، كقتل الأنفس، وقال بعضهم: يجوز أن يستعبدنا الله تعالى سؤاله أن لا يفعل ما يعلم أنه لا يفعله ..\nإن قيل: ما الفرق بين العفو والغفران والرحمة؟ وما وجه هذه الترتيب؟\nقيل: العفو: إزالة الذنب بترك عقوبته، والغفران ستر الذنوب، وكشف الإحسان الذي غطى به، والرحمة إفاضة الإحسان عليه، وقد علم أن الثاني أبلغ من الأول ، والثالث أبلغ من الثاني ...\nوقوله: ﴿أَنتَ مَوۡلَىٰنَا﴾⟪2:286⟫ كقوله: ﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ﴾⟪2:257⟫ وقوله: ﴿فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ﴾⟪2:286⟫ فنصرة الله للمؤمنين على وجهين أحدهما: من حث الحجة، وقد فعل.\nوالثاني: من المداولة التي قال: ﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ﴾⟪3:140⟫ وهذا هو المسؤول أن يجعل لنا عليهم دولة، ولا يجعل لهم علينا دولة، ووجه ثالث وهو أن الله قد نصر المؤمنين كافة حجة وملجأ، ومعونة وظهورا على الدين كله لكن قد يلحق المسلم غلبة من جهة كافر، وهو المشار إليه بقول أمير المؤمنين - رضي الله عنه: \" إن للباطل جولة ثم يضمحل \"، فكأن الاستعاذة بالله أن يقينا من هذه الجولة من الكفار ..\n\" تم بحمد الله تفسير سورة البقرة \"\n⟦2:400⟧\nبسم الله الرحمن الرحيم\nالكتاب: تفسير الراغب الأصفهاني\n(من أول سورة آل عمران - وحتى الآية 113 من سورة النساء)\nتحقيق ودراسة: د. عادل بن علي الشدي\nدار النشر: دار الوطن - الرياض\nالطبعة الأولى: 1424 ه - 2003 م\nعدد الأجزاء: 2\n[ترقيم الكتاب موافق للمطبوع]"}];
